12	void *memcpy(void *dest, const void *src, size_t n) {
13	    uint8_t *d = (uint8_t *)dest;
14	    const uint8_t *s = (const uint8_t *)src;
15	    while (n--) {
16	        *d++ = *s++;
17	    }
18	    return dest;
19	}
20	
21	void *memmove(void *dest, const void *src, size_t n) {
22	    uint8_t *d = (uint8_t *)dest;
23	    const uint8_t *s = (const uint8_t *)src;
24	    if (d < s) {
25	        while (n--) {
26	            *d++ = *s++;
27	        }
28	    } else {
29	        d += n;
30	        s += n;
31	        while (n--) {
32	            *--d = *--s;
33	        }
34	    }
35	    return dest;
36	}
37	
38	int memcmp(const void *s1, const void *s2, size_t n) {
39	    const uint8_t *p1 = (const uint8_t *)s1;
40	    const uint8_t *p2 = (const uint8_t *)s2;
41	    while (n--) {
42	        if (*p1 != *p2) {
43	            return *p1 - *p2;
44	        }
45	        p1++;
46	        p2++;
47	    }
48	    return 0;
49	}
